package main

import (
	"fmt"
	"regexp"
)

func main() {
	// Example of a simple input validation function
	productName := "Sample Product"
	isValid := validateProductName(productName)
	fmt.Printf("Is the product name valid? %v\n", isValid)
}

func validateProductName(name string) bool {
	// Check if the product name is not empty and matches a specific pattern
	return name != "" && regexp.MustCompile(`^[a-zA-Z0-9\s]+$`).MatchString(name)
}
